files.accept-html.mjs:
import fs from 'node:fs';
import assert from 'node:assert/strict';
const h = fs.readFileSync('docs/wireframe.html', 'utf8');
assert.match(h, /<form/i);
assert.match(h, /<input/i);
assert.match(h, /Add/);
assert.ok((h.match(/<li/gi) || []).length >= 3);

files.accept-png.mjs:
import fs from 'node:fs';
import assert from 'node:assert/strict';
const b = fs.readFileSync('docs/wireframe.png');
assert.equal(b.subarray(0, 8).toString('hex'), '89504e470d0a1a0a');
assert.ok(b.readUInt32BE(16) >= 200 && b.readUInt32BE(20) >= 200, 'dimensions');
assert.ok(b.length > 2000, 'size');
